<script lang="ts">
  import {command,request,permitted} from '#lib/client/api.ts';
  import type {AppData} from '#lib/client/types.ts';
  import type {AssistantSource} from '#lib/client/assistant.ts';
  import ReferencePicker from './ReferencePicker.svelte';
  import Status from './Status.svelte';
  import Icon from './Icon.svelte';
  let {data,rows=$bindable([]),disabled=false}:{data:AppData;rows?:AssistantSource[];disabled?:boolean}=$props();
  function add(){if(rows.length<2)rows=[...rows,{key:crypto.randomUUID(),documentId:'',name:'',pageNumber:1,includeImage:false}];}
  function selected(row:AssistantSource,value:string,choice?:{name:string}){row.documentId=value;row.name=choice?.name||'Ausgewählte Unterlage';row.preview=undefined;row.includeImage=false;row.error='';}
  function identity(row:AssistantSource){return row.documentId+':'+row.pageNumber;}
  async function preview(row:AssistantSource,refresh=false){if(disabled||row.working||!row.documentId)return;const target=identity(row);row.working=true;row.error='';try{if(!Number.isInteger(row.pageNumber)||Number(row.pageNumber)<1||Number(row.pageNumber)>1000)throw new Error('Eine konkrete Seite von 1 bis 1.000 wählen. Bei einem Foto verwenden Sie Seite 1.');const result=refresh?await request('/api/v1/planning/source-preview/'+row.preview?.job_id,undefined,'GET'):await command('documents.preview',undefined,{document_id:row.documentId,page_index:Number(row.pageNumber)-1,ai_preview:true});if(identity(row)===target)row.preview=result;}catch(cause){if(identity(row)===target)row.error=cause instanceof Error?cause.message:'Die Bildreferenz konnte nicht vorbereitet werden.';}finally{row.working=false;}}
  function imageUrl(row:AssistantSource){return row.preview?.document_id&&row.preview?.document_version_id?`/api/v1/documents/${row.preview.document_id}/download?version=${row.preview.document_version_id}&inline=1`:null;}
</script>
<details class="assistant-sources"><summary>Unterlagen hinzufügen · optional{rows.length?` · ${rows.length}/2`:''}<Icon name="file" size={14}/></summary><div class="assistant-source-body"><p class="field-help">Höchstens zwei bewusst ausgewählte Quellen. Übermittelt werden vorhandene Textauszüge und nur auf Wunsch eine kleine Bildreferenz der bezeichneten Seite.</p>
{#each rows as row,index (row.key)}<fieldset class="assistant-source" disabled={disabled||row.working}><div class="assistant-source-header"><h3>Quelle {index+1}</h3><button type="button" class="icon-button" aria-label={`Quelle ${index+1} entfernen`} onclick={()=>rows=rows.filter(item=>item.key!==row.key)}><Icon name="trash" size={15}/></button></div><div class="field"><label for={`assistant-source-${row.key}`}>Geprüfte Unterlage *</label><ReferencePicker id={`assistant-source-${row.key}`} bind:value={row.documentId} reference="documents" initial={data.lookups.documents||[]} required onchange={(value,choice)=>selected(row,value,choice)}/></div><div class="field mt"><label for={`assistant-page-${row.key}`}>Seite im Original *</label><input id={`assistant-page-${row.key}`} type="number" min="1" max="1000" step="1" bind:value={row.pageNumber} required oninput={()=>{row.preview=undefined;row.error='';}}/><span class="field-help">Die sichtbare Seitennummer. Bei einem Foto: Seite 1.</span></div><label class="check-field mt"><input type="checkbox" bind:checked={row.includeImage}/><span>Sichtbaren Bild- oder PDF-Inhalt dieser Seite mitgeben</span></label>{#if row.includeImage}<p class="field-help mt">Zuerst eine private Vorschau bis 512 Pixel vorbereiten. Der gesamte PDF-Inhalt und frühere Unterhaltungen werden nicht als Datei mitgesendet.</p><div class="inline-actions mt"><button type="button" class="btn small" disabled={!row.documentId||!permitted(data,'documents')} onclick={()=>preview(row)}><Icon name={row.working?'refresh':'file'} size={14}/>{row.working?'Wird vorbereitet …':'Bild vorbereiten'}</button>{#if row.preview?.job_id}<button type="button" class="btn small" onclick={()=>preview(row,true)}><Icon name="refresh" size={14}/>Status aktualisieren</button>{/if}</div>{#if !permitted(data,'documents')}<p class="field-help mt">Für die Bildvorbereitung ist das Dokumentenrecht erforderlich. Vorhandene Textauszüge bleiben eine getrennte Auswahl.</p>{/if}{#if row.preview}<div class="assistant-preview-status mt" aria-live="polite"><Status value={row.preview.status}/>{#if row.preview.message}<p class="field-help mt">{row.preview.message}</p>{/if}{#if row.preview.status==='completed'&&imageUrl(row)}<img src={imageUrl(row)!} alt={`Vorbereitete Bildreferenz von ${row.name}, Seite ${row.pageNumber}`} loading="lazy"/><p class="field-help">Vorbereitet: {row.preview.width} × {row.preview.height} Pixel · Quelle und Seite vor dem Senden prüfen.</p>{:else if ['pending','running','retry'].includes(row.preview.status)}<p class="field-help mt">Die konkrete Seite wird verarbeitet. Aktualisieren Sie den Status manuell; anschließend wird das Senden freigegeben.</p>{/if}</div>{/if}{:else}<p class="field-help mt">Nur vorhandene Textauszüge dieser Seite. Fehlt eine Erkennung, bleibt das für den Assistenten kenntlich.</p>{/if}{#if row.error}<p class="field-error mt" role="alert">{row.error}</p>{/if}</fieldset>{/each}
<button type="button" class="btn small mt" disabled={disabled||rows.length>=2} onclick={add}><Icon name="plus" size={14}/>Quelle auswählen</button><p class="field-help mt">Personalunterlagen bleiben außerhalb der KI. Die Quelle dient als ungeprüfter Bezug; Maße und Aussagen müssen fachlich kontrolliert werden.</p></div></details>
<style>.assistant-sources{border-top:1px solid var(--line);padding-top:11px;margin-bottom:15px}.assistant-sources>summary{font-size:12px;display:flex;align-items:center;justify-content:space-between;gap:10px;cursor:pointer;min-height:35px;color:var(--forest)}.assistant-source-body{max-height:36dvh;overflow:auto;padding:9px 2px 3px}.assistant-source{border:1px solid var(--line);border-radius:5px;margin:17px 0 0;padding:14px;min-width:0;background:var(--paper)}.assistant-source-header{display:flex;align-items:center;justify-content:space-between;gap:15px;margin-bottom:12px}.assistant-source-header h3{font-size:13px;font-weight:550}.assistant-source :global(.field label){font-size:12px}.assistant-source :global(.field-help){font-size:11px;line-height:1.65}.assistant-source :global(.reference-search>summary){font-size:11px}.assistant-preview-status img{display:block;max-width:100%;max-height:140px;object-fit:contain;margin:13px 0 10px;border:1px solid var(--line);background:white}.assistant-source :global(.reference-search-controls){flex-wrap:wrap}.assistant-source :global(.reference-search-controls input){flex-basis:100%}.assistant-source .check-field{font-size:12px;align-items:start}.assistant-source .check-field input{flex:none}@media(max-width:760px){.assistant-sources>summary{font-size:13px;min-height:44px}.assistant-source-body{max-height:34dvh}.assistant-source :global(.field-help){font-size:12px}.assistant-source .check-field{font-size:13px}.assistant-source .btn{min-height:44px}}</style>
